"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[2777],{49253(e,t,s){s.r(t),s.d(t,{assets:()=>l,contentTitle:()=>u,default:()=>d,frontMatter:()=>r,metadata:()=>n,toc:()=>o});const n=JSON.parse('{"id":"learning/courses/integrating-quantum-and-high-performance-computing/next-steps","title":"Prochaines \xe9tapes","description":"Cette le\xe7on examine l\'\xe9tat du calcul quantique et comment les humains approchent l\'avantage quantique.","source":"@site/i18n/fr/docusaurus-plugin-content-docs/current/learning/courses/integrating-quantum-and-high-performance-computing/next-steps.mdx","sourceDirName":"learning/courses/integrating-quantum-and-high-performance-computing","slug":"/learning/courses/integrating-quantum-and-high-performance-computing/next-steps","permalink":"/learning/courses/integrating-quantum-and-high-performance-computing/next-steps","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/learning/courses/integrating-quantum-and-high-performance-computing/next-steps.mdx","tags":[],"version":"current","frontMatter":{"title":"Prochaines \xe9tapes","sidebar_label":"Prochaines \xe9tapes","description":"Cette le\xe7on examine l\'\xe9tat du calcul quantique et comment les humains approchent l\'avantage quantique.","notebook_path":"learning/courses/integrating-quantum-and-high-performance-computing/next-steps.ipynb"},"sidebar":"tutorialsSidebar","previous":{"title":"SQD et SKQD","permalink":"/learning/courses/integrating-quantum-and-high-performance-computing/sqd-skqd"},"next":{"title":"Examen | Int\xe9gration du quantique et du calcul haute performance","permalink":"/learning/courses/integrating-quantum-and-high-performance-computing/exam"}}');var i=s(74848),a=s(28453);const r={title:"Prochaines \xe9tapes",sidebar_label:"Prochaines \xe9tapes",description:"Cette le\xe7on examine l'\xe9tat du calcul quantique et comment les humains approchent l'avantage quantique.",notebook_path:"learning/courses/integrating-quantum-and-high-performance-computing/next-steps.ipynb"},u="Perspectives et orientations futures {#future-outlook-and-direction}",l={},o=[{value:"Pourquoi maintenant ?",id:"why-now",level:3},{value:"5.1 La vue d&#39;ensemble",id:"the-big-picture",level:2},{value:"Les grandes id\xe9es",id:"big-ideas",level:2},{value:"Les perspectives d&#39;IBM pour l&#39;avenir",id:"ibms-outlook-for-the-future",level:2},{value:"R\xe9sum\xe9",id:"summary",level:2}];function c(e){const t={a:"a",h1:"h1",h2:"h2",h3:"h3",header:"header",img:"img",li:"li",p:"p",ul:"ul",...(0,a.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:["\n","\n",(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"future-outlook-and-direction",children:"Perspectives et orientations futures"})}),"\n",(0,i.jsx)(t.p,{children:"Jusqu'ici, nous avons appris la motivation pour utiliser \xe0 la fois le calcul haute performance (HPC) et le calcul quantique pour r\xe9soudre des probl\xe8mes scientifiques. Nous avons d\xe9fini les ressources de calcul classique et quantique, notamment les CPU, GPU et QPU, et discut\xe9 de la fa\xe7on de les mettre \xe0 l'\xe9chelle et de les g\xe9rer gr\xe2ce \xe0 des techniques comme la mise \xe0 l'\xe9chelle verticale et horizontale, la planification et la gestion des charges de travail. De plus, nous avons explor\xe9 les mod\xe8les de programmation pour les QPU (tels que les circuits quantiques et les primitives comme Sampler et Estimator) et les ordinateurs classiques, y compris les pratiques de programmation parall\xe8le avec MPI, un outil puissant du calcul h\xe9t\xe9rog\xe8ne quantique-classique. Enfin, nous avons \xe9tudi\xe9 et mis en pratique des algorithmes avanc\xe9s quantiques par \xe9chantillonnage, comme la Diagonalisation quantique par \xe9chantillonnage (SQD) et la Diagonalisation quantique de Krylov par \xe9chantillonnage (SKQD). Ces algorithmes exploitent la m\xe9thode des sous-espaces pour estimer pr\xe9cis\xe9ment l'\xe9nergie de l'\xe9tat fondamental de mol\xe9cules et de mat\xe9riaux en pr\xe9parant et en \xe9chantillonnant des \xe9tats quantiques, qui d\xe9finissent un sous-espace pour la diagonalisation classique, une combinaison de diff\xe9rents mod\xe8les de programmation sur un ensemble de ressources h\xe9t\xe9rog\xe8nes. Avec ces concepts fondamentaux du supercalcul quantique et classique, nous ne parlons plus de l'un rempla\xe7ant l'autre, mais de cr\xe9er un syst\xe8me int\xe9gr\xe9 et puissant qui fonctionne en synergie \u2014 une combinaison pr\xeate \xe0 inaugurer l'aube de l'avantage quantique."}),"\n",(0,i.jsx)(t.h3,{id:"why-now",children:"Pourquoi maintenant ?"}),"\n",(0,i.jsxs)(t.p,{children:["La communaut\xe9 a d\xe9j\xe0 franchi le cap de l'\xab utilit\xe9 quantique \xbb \u2014 o\xf9 les ordinateurs quantiques ont \xe9t\xe9 prouv\xe9s pour la premi\xe8re fois comme des outils scientifiques utiles capables de calculs au-del\xe0 de la simulation classique par force brute. Cette \xe8re d'utilit\xe9 a commenc\xe9 avec le d\xe9sormais c\xe9l\xe8bre ",(0,i.jsx)(t.a,{href:"https://www.nature.com/articles/s41586-023-06096-3",children:"article sur l'utilit\xe9"})," pr\xe9sent\xe9 en couverture de Nature en 2023, et s'est poursuivie par des dizaines de publications de partenaires, clients et chercheurs d'IBM Quantum\xae. Maintenant, l'attention s'est port\xe9e sur la prochaine fronti\xe8re critique : atteindre l'avantage quantique. Pendant longtemps, le terme \xab avantage quantique \xbb a souffert de d\xe9finitions impr\xe9cises. Cet ",(0,i.jsx)(t.a,{href:"https://arxiv.org/abs/2506.20658",children:"article"})," a propos\xe9 une d\xe9finition concr\xe8te, que nous utiliserons ici. Plus pr\xe9cis\xe9ment, l'avantage quantique d\xe9signe l'ex\xe9cution d'une t\xe2che de traitement de l'information sur du mat\xe9riel quantique qui satisfait deux crit\xe8res essentiels :"]}),"\n",(0,i.jsx)(t.p,{children:"i) La correction du r\xe9sultat peut \xeatre rigoureusement valid\xe9e, et"}),"\n",(0,i.jsx)(t.p,{children:"ii) Elle est r\xe9alis\xe9e avec une s\xe9paration quantique qui offre de mani\xe8re d\xe9montrable une efficacit\xe9, une rentabilit\xe9 ou une pr\xe9cision sup\xe9rieures \xe0 ce qui est atteignable avec le seul calcul classique."}),"\n",(0,i.jsx)(t.p,{children:"Il est pr\xe9vu que l'avantage quantique commence \xe0 \xe9merger d'ici fin 2026 et qu'il le fasse gr\xe2ce \xe0 la combinaison des ressources quantiques et HPC. Cette le\xe7on d\xe9crit la vision centrale de ce nouveau paradigme, d\xe9taille les id\xe9es cl\xe9s \xe0 venir, et pr\xe9sente une perspective future ancr\xe9e dans un cadre v\xe9rifiable et ind\xe9pendant de la plateforme pour d\xe9montrer et r\xe9aliser un v\xe9ritable avantage quantique."}),"\n",(0,i.jsx)(t.h2,{id:"the-big-picture",children:"5.1 La vue d'ensemble"}),"\n",(0,i.jsx)(t.p,{children:"Pour la premi\xe8re fois, nous assistons \xe0 un tournant significatif dans l'histoire du calcul \u2014 l'\xe8re du supercalcul quantique centr\xe9 (QCSC), un paradigme \xe9mergent qui int\xe8gre \xe9troitement les unit\xe9s de traitement quantique (QPU) avec les supercalculateurs classiques. La vision n'est pas que les syst\xe8mes quantiques remplacent les syst\xe8mes classiques, mais de d\xe9montrer que cette architecture h\xe9t\xe9rog\xe8ne \u2014 o\xf9 \xab quantique plus classique \xbb peut surpasser le classique seul \u2014 est la voie la plus puissante \xe0 suivre. Dans ce mod\xe8le, les QPU sont envisag\xe9s comme des co-processeurs sp\xe9cialis\xe9s, travaillant aux c\xf4t\xe9s des CPU et GPU pour s'attaquer \xe0 des probl\xe8mes de calcul intraitables pour les ordinateurs classiques."}),"\n",(0,i.jsx)(t.p,{children:"Le plein potentiel de cette nouvelle architecture ne peut \xeatre r\xe9alis\xe9 qu'en mettant ces outils puissants entre les mains du plus grand nombre d'utilisateurs possible. Cette vision prend d\xe9j\xe0 forme \xe0 travers le d\xe9ploiement de syst\xe8mes quantiques dans des centres de calcul haute performance (HPC) \xe9tablis et le d\xe9veloppement de logiciels, comme les plugins Slurm quantiques, qui rationalisent leur int\xe9gration dans les flux de travail classiques existants. En rendant ces syst\xe8mes h\xe9t\xe9rog\xe8nes plus accessibles \xe0 la communaut\xe9 de recherche \xe9largie, nous cr\xe9ons l'environnement n\xe9cessaire \xe0 l'innovation et \xe0 la d\xe9couverte."}),"\n",(0,i.jsx)(t.p,{children:"Cette strat\xe9gie combinant technologie int\xe9gr\xe9e et large base d'utilisateurs est la fa\xe7on dont nous croyons que la communaut\xe9 atteindra l'avantage quantique dans un avenir proche. L'avantage quantique n'est pas un jalon unique et d\xe9finitif, mais un processus \u2014 une s\xe9quence de d\xe9monstrations de plus en plus robustes qui seront examin\xe9es, reproduites et remises en question par la communaut\xe9 jusqu'\xe0 ce qu'un consensus scientifique soit atteint. C'est la voie pour d\xe9montrer, d'ici fin 2026, les premi\xe8res instances cr\xe9dibles et v\xe9rifiables o\xf9 cette nouvelle fa\xe7on de calculer r\xe9sout des probl\xe8mes pratiques plus efficacement, de fa\xe7on plus rentable ou plus pr\xe9cise que ce qui est atteignable avec le seul calcul classique."}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.img,{src:"/learning/images/courses/integrating-quantum-and-high-performance-computing/next-steps/advantage.svg",alt:"Un diagramme montrant le co\xfbt des simulations en fonction de la complexit\xe9 croissante des circuits pour les ordinateurs classiques et les ordinateurs quantiques avec att\xe9nuation des erreurs. L\xe0 o\xf9 les courbes se croisent, l'espace entre elles correspond \xe0 l'avantage quantique."})}),"\n",(0,i.jsx)(t.h2,{id:"big-ideas",children:"Les grandes id\xe9es"}),"\n",(0,i.jsx)(t.p,{children:"Pour r\xe9aliser cette vision, plusieurs questions et id\xe9es critiques doivent \xeatre abord\xe9es."}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsxs)(t.li,{children:["\n",(0,i.jsx)(t.p,{children:"Partitionnement optimal des charges de travail : Du c\xf4t\xe9 logiciel, le d\xe9fi consiste \xe0 g\xe9rer des flux de travail hybrides complexes. Orchestrer l'ex\xe9cution transparente de t\xe2ches sur des ressources \xe0 la fois quantiques et classiques n\xe9cessite des outils sophistiqu\xe9s. Cela inclut des middleware quantiques-HPC et une infrastructure d'ex\xe9cution con\xe7ue pour g\xe9rer la planification des t\xe2ches, la gestion des ressources et les flux de donn\xe9es dans cet environnement h\xe9t\xe9rog\xe8ne. De plus, d\xe9velopper des techniques pour parall\xe9liser efficacement les circuits quantiques ou les d\xe9composer en parties plus petites et g\xe9rables est crucial pour maximiser l'utilit\xe9 du mat\xe9riel quantique actuel."}),"\n"]}),"\n",(0,i.jsxs)(t.li,{children:["\n",(0,i.jsx)(t.p,{children:"Tol\xe9rance aux fautes au niveau syst\xe8me : La solution ultime pour prot\xe9ger l'information quantique du bruit est le calcul quantique tol\xe9rant aux fautes (FTQC), o\xf9 l'information est encod\xe9e dans des \xab qubits logiques \xbb robustes. Bien que les codes de correction d'erreurs quantiques \xe0 faible densit\xe9 de parit\xe9 (qLDPC) \xe9mergents offrent une voie pour r\xe9duire l'\xe9norme surco\xfbt en ressources requis, la mise en \u0153uvre d'une tol\xe9rance aux fautes compl\xe8te n'est pas attendue comme \xe9tant viable dans l'imm\xe9diat proche. Parall\xe8lement, l'att\xe9nuation des erreurs utilise le post-traitement classique pour r\xe9duire ou \xe9liminer le biais dans les calculs caus\xe9 par le bruit, ce qui est \xe9galement un \xe9l\xe9ment critique pour atteindre des syst\xe8mes quantiques tol\xe9rants aux fautes au niveau syst\xe8me. Des m\xe9thodes puissantes d'att\xe9nuation des erreurs sont d\xe9j\xe0 d\xe9ploy\xe9es en tant que service, d\xe9montrant la puissance de l'architecture QCSC. Par exemple :"}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsxs)(t.li,{children:["La ",(0,i.jsx)(t.a,{href:"/guides/algorithmiq-tem",children:"Tensor Network Error Mitigation"})," (TEM) d'Algorithmiq g\xe8re le bruit dans le post-traitement logiciel, exploitant les ressources HPC classiques pour \xe9tendre la port\xe9e des QPU actuels."]}),"\n",(0,i.jsxs)(t.li,{children:["La ",(0,i.jsx)(t.a,{href:"/guides/qedma-qesem",children:"Quantum Error Suppression and Error Mitigation"})," (QESEM) de Qedma combine la suppression des erreurs au niveau mat\xe9riel avec l'att\xe9nuation pour am\xe9liorer la fiabilit\xe9 des calculs quantiques \xe0 grande \xe9chelle."]}),"\n"]}),"\n"]}),"\n",(0,i.jsxs)(t.li,{children:["\n",(0,i.jsx)(t.p,{children:"D\xe9mocratisation de l'acc\xe8s : Rendre ces puissants syst\xe8mes hybrides largement accessibles est essentiel pour acc\xe9l\xe9rer l'innovation. Cela se concr\xe9tise d\xe9j\xe0 par le d\xe9ploiement physique de syst\xe8mes quantiques dans des centres HPC et la publication de plugins Slurm pour une int\xe9gration rationalis\xe9e. Pour faciliter cette int\xe9gration, les deux entreprises ont publi\xe9 des plugins Slurm, afin que les charges de travail quantiques puissent \xeatre g\xe9r\xe9es avec des planificateurs HPC standard. De plus, des piles logicielles compl\xe8tes comme Qiskit fournissent un environnement d'ex\xe9cution bas\xe9 sur le cloud pour l'ex\xe9cution de circuits quantiques \xe0 faible latence, orchestrant des t\xe2ches hybrides complexes et fournissant des outils pour la compilation, l'optimisation et l'att\xe9nuation des erreurs. Le mat\xe9riel quantique en acc\xe8s libre et les paquets de d\xe9veloppement open-source joueront sans aucun doute un r\xf4le critique."}),"\n"]}),"\n"]}),"\n",(0,i.jsx)(t.h2,{id:"ibms-outlook-for-the-future",children:"Les perspectives d'IBM pour l'avenir"}),"\n",(0,i.jsxs)(t.p,{children:["La ",(0,i.jsx)(t.a,{href:"https://www.ibm.com/quantum/hardware#roadmap",children:"Feuille de route de d\xe9veloppement quantique IBM"})," est une bonne illustration de cette vue d'ensemble et de ces grandes id\xe9es."]}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.img,{src:"/learning/images/courses/integrating-quantum-and-high-performance-computing/next-steps/roadmap.svg",alt:"La Feuille de route de d\xe9veloppement quantique IBM"})}),"\n",(0,i.jsx)(t.p,{children:"La feuille de route mat\xe9rielle d'IBM Quantum est guid\xe9e par un focus sur l'augmentation de l'\xe9chelle et de la connectivit\xe9 des qubits. La s\xe9rie Nighthawk (2025-2028) utilise une nouvelle architecture en r\xe9seau carr\xe9 pour am\xe9liorer la connectivit\xe9, tandis que le processeur Loon (2025) introduit des \xab c-coupleurs \xbb pour permettre une connectivit\xe9 non locale des qubits, essentielle pour le calcul quantique tol\xe9rant aux fautes (FTQC). Cette feuille de route culmine dans les syst\xe8mes IBM Quantum Starling (2029) et Blue Jay (2033+), con\xe7us pour fournir un calcul tol\xe9rant aux fautes \xe0 grande \xe9chelle avec des millions de portes et des milliers de qubits logiques."}),"\n",(0,i.jsx)(t.p,{children:"La strat\xe9gie logicielle et middleware repose sur quatre objectifs cl\xe9s : ex\xe9cuter avec pr\xe9cision, orchestrer les charges de travail, d\xe9couvrir de nouveaux algorithmes, et les appliquer \xe0 des cas d'utilisation sp\xe9cifiques. La feuille de route inclut des am\xe9liorations continues comme les circuits dynamiques \xe0 l'\xe9chelle utilitaire (2025) et de nouveaux outils de profilage (2026) pour assurer une ex\xe9cution efficace. Pour l'orchestration des charges de travail, le C-API (2025) et les futurs acc\xe9l\xe9rateurs de flux de travail (2027) int\xe9greront le calcul haute performance (HPC) quantique et classique. De plus, IBM\xae introduira des outils de cartographie utilitaire (2026) et de nouvelles biblioth\xe8ques de circuits (2029) pour faciliter la d\xe9couverte et l'application de nouveaux algorithmes."}),"\n",(0,i.jsx)(t.h2,{id:"summary",children:"R\xe9sum\xe9"}),"\n",(0,i.jsx)(t.p,{children:"Nous avons explor\xe9 les grandes vues d'ensemble et les grandes id\xe9es derri\xe8re l'objectif QCSC, et nous avons examin\xe9 la feuille de route d'IBM en mati\xe8re de d\xe9veloppement et d'innovation du calcul quantique. Ce voyage, comme nous l'avons vu, est un marathon, pas un sprint. Si IBM est engag\xe9 \xe0 fournir des ordinateurs quantiques de plus en plus puissants, nos progr\xe8s ne sont qu'une partie de l'\xe9quation. Il est crucial que la communaut\xe9 quantique continue de d\xe9velopper de nouveaux algorithmes, ouvrant la voie aux applications qui apporteront v\xe9ritablement un calcul quantique utile au monde."}),"\n",(0,i.jsx)(t.p,{children:"Pour y parvenir, nous devons travailler ensemble. Cela signifie \xe9tablir des probl\xe8mes de r\xe9f\xe9rence standardis\xe9s avec l'aide d'experts classiques pour assurer la pertinence et l'\xe9quit\xe9. Cela n\xe9cessite \xe9galement de publier des m\xe9thodologies et des ensembles de donn\xe9es d\xe9taill\xe9s pour permettre la reproductibilit\xe9, et de maintenir des classements en acc\xe8s libre pour suivre nos progr\xe8s collectifs."}),"\n",(0,i.jsx)(t.p,{children:"Il n'y a jamais eu de moment aussi excitant pour faire partie de cette communaut\xe9. En adoptant ces meilleures pratiques et en poursuivant notre exploration, nous pouvons travailler ensemble pour r\xe9aliser le plein potentiel de l'avantage quantique."})]})}function d(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(c,{...e})}):c(e)}},28453(e,t,s){s.d(t,{R:()=>r,x:()=>u});var n=s(96540);const i={},a=n.createContext(i);function r(e){const t=n.useContext(a);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function u(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),n.createElement(a.Provider,{value:t},e.children)}}}]);